CREATE TABLE `Prescription` (
  `prescriptionId` int NOT NULL,
  `healthCardNo` varchar(20) NOT NULL,
  `staffId` int NOT NULL,
  `medicationId` int NOT NULL,
  `prescriptionDate` date NOT NULL,
  `dosage` varchar(100) DEFAULT NULL,
